() => { 
  const closeButtons = document.querySelectorAll('button[aria-label="关闭"]');
  let results = [];
  closeButtons.forEach((b, i) => {
    results.push({index: i, label: b.getAttribute('aria-label'), visible: b.offsetParent !== null});
  });
  return results;
}

() => {
  // Find and click all close buttons
  const closeButtons = document.querySelectorAll('button[aria-label="关闭"]');
  for (const b of closeButtons) {
    b.click();
  }
  return 'Clicked ' + closeButtons.length + ' close buttons';
}

() => {
  const overlays = document.querySelectorAll('[role="dialog"], [aria-modal="true"], .overlay');
  const results = [];
  overlays.forEach((o, i) => {
    results.push({index: i, tag: o.tagName, role: o.getAttribute('role'), ariaModal: o.getAttribute('aria-modal'), className: o.className});
  });
  // Also check for consent
  const allButtons = document.querySelectorAll('button');
  const visibleButtons = [];
  allButtons.forEach((b, i) => {
    if (b.offsetParent !== null && b.textContent.trim()) {
      visibleButtons.push({index: i, text: b.textContent.trim().substring(0, 50)});
    }
  });
  return {overlays: results, buttons: visibleButtons.slice(0, 30)};
}

() => {
  const buttons = Array.from(document.querySelectorAll('button')).filter(b => b.offsetParent !== null && b.textContent.trim());
  return buttons.map(b => b.textContent.trim().substring(0, 60));
}
